import json, yaml

RESULT_FILE = "/home/ubuntu/.claude-account-3/projects/-home-ubuntu--agent-ml-research-idea-gen-0509-4-projects-trace-verdict-study--claude-sessions-reviewer-4eb9adda/60bff34d-71f2-4ba6-954a-e9e228ca0a98/tool-results/mcp-agent-ml-research-read_registry-1779488984049.txt"

with open(RESULT_FILE) as f:
    raw = json.load(f)

data = yaml.safe_load(raw['result'])
experiments = data['data']['experiments']

# Final comprehensive table - corrected classification
# For Qwen-7B: unprefixed experiments + qwen7b_ prefixed
# For conditions: use the "latest valid" experiment when versioned reruns exist

def get_valid_experiments(experiments, model_prefix, condition):
    """Get valid (non-killed, non-failed) experiments for a model-condition pair"""
    results = {}
    for eid, exp in experiments.items():
        eid_lower = eid.lower()

        # Match model
        if model_prefix == '':  # Qwen-7B (default)
            # Must NOT start with any other model prefix
            if any(eid_lower.startswith(p) for p in ['codellama', 'deepseek', 'qwen15b', 'qwen1.5b']):
                continue
            # Can start with qwen7b_ or have no prefix
            if eid_lower.startswith('qwen7b_'):
                remainder = eid_lower[7:]  # len('qwen7b_')
            else:
                remainder = eid_lower
        elif model_prefix == 'codellama13b':
            if not (eid_lower.startswith('codellama13b_') or eid_lower.startswith('codellama_')):
                continue
            remainder = eid_lower.split('_', 1)[1] if eid_lower.startswith('codellama_') else eid_lower[13:]
        elif model_prefix == 'deepseek':
            if not eid_lower.startswith('deepseek_'):
                continue
            remainder = eid_lower[9:]
        elif model_prefix == 'qwen15b':
            if not (eid_lower.startswith('qwen15b_') or eid_lower.startswith('qwen1.5b_')):
                continue
            remainder = eid_lower.split('_', 1)[1] if eid_lower.startswith('qwen1.5b_') else eid_lower[8:]
        else:
            continue

        # Match condition - must start with condition name
        # Skip cross_, debugbench_, fewshot_, zeroshot_, regex_, calibration_, attention_, eval_, gradient_masking
        skip = ['cross_', 'debugbench_', 'fewshot_', 'zeroshot_', 'regex_', 'calibration_', 'attention_', 'eval_', 'gradient_masking', 'exception_only_dynamics', 'full_trace_dynamics']
        if any(remainder.startswith(s) for s in skip):
            continue

        # For 'full_trace' condition: only base full_trace, not tail/head/label variants
        if condition == 'full_trace':
            if not remainder.startswith('full_trace_seed') and not remainder.startswith('full_trace_tail512'):
                continue
            # Only base full_trace (not tail512)
            if 'tail' in remainder or 'head' in remainder or 'label' in remainder:
                continue
        elif condition == 'vota':
            if not remainder.startswith('vota_seed'):
                continue
        elif condition == 'no_trace':
            if not remainder.startswith('no_trace_seed'):
                continue
        elif condition == 'label_only':
            # Include full_trace_label_only as label_only? No, keep separate
            if not remainder.startswith('label_only_seed'):
                continue
        elif condition == 'nomarker':
            if not remainder.startswith('nomarker_seed'):
                continue
        else:
            if not remainder.startswith(condition + '_seed'):
                continue

        import re
        seed_match = re.search(r'seed(\d+)', remainder)
        if not seed_match:
            continue
        seed = int(seed_match.group(1))

        conc = str(exp.get('conclusion', '')).lower()
        acc = exp.get('metrics', {}).get('accuracy')

        # For versioned experiments, keep the latest successful version
        base_key = (seed, condition)
        version = 0
        v_match = re.search(r'_v(\d+)$', eid)
        if v_match:
            version = int(v_match.group(1))

        if base_key not in results or version > results[base_key].get('version', 0):
            if conc in ('success', ''):
                results[base_key] = {
                    'exp_id': eid,
                    'seed': seed,
                    'conclusion': exp.get('conclusion'),
                    'accuracy': acc,
                    'version': version,
                    'all_versions': results.get(base_key, {}).get('all_versions', []) + [eid]
                }
            elif base_key not in results:
                results[base_key] = {
                    'exp_id': eid,
                    'seed': seed,
                    'conclusion': exp.get('conclusion'),
                    'accuracy': acc,
                    'version': version,
                    'all_versions': [eid]
                }

    return results

models = [
    ('', 'Qwen-7B'),
    ('qwen15b', 'Qwen-1.5B'),
    ('codellama13b', 'CodeLlama-13B'),
    ('deepseek', 'DeepSeek-6.7B'),
]

conditions = ['exception_only', 'ae_only', 'vota', 'loop_only', 'full_trace', 'no_trace', 'nomarker', 'label_only']

print("FINAL SEED COVERAGE TABLE (using latest valid version per seed)")
print("=" * 130)
print(f"| {'Model':<16} | {'Condition':<16} | {'#Seeds':>6} | {'Seeds':<16} | {'Accuracies':<30} | {'Anomalies':<30} |")
print("|" + "-"*18 + "|" + "-"*18 + "|" + "-"*8 + "|" + "-"*18 + "|" + "-"*32 + "|" + "-"*32 + "|")

for model_prefix, model_name in models:
    for condition in conditions:
        valid = get_valid_experiments(experiments, model_prefix, condition)
        seeds = sorted(set(v['seed'] for v in valid.values()))
        n_seeds = len(seeds)
        seed_str = ','.join(str(s) for s in seeds) if seeds else 'NONE'

        accs = []
        anomalies = []
        for s in seeds:
            key = (s, condition)
            if key in valid:
                v = valid[key]
                acc = v['accuracy']
                conc = str(v['conclusion']).lower()
                if acc is not None:
                    accs.append(f"{acc:.4f}")
                else:
                    accs.append("N/A")
                if conc in ('negative', 'failed', 'killed', 'collapsed', ''):
                    anomalies.append(f"s{s}:{conc}")
                if acc == 'collapsed':
                    anomalies.append(f"s{s}:COLLAPSED")

        acc_str = ','.join(accs) if accs else '--'
        anom_str = '; '.join(anomalies) if anomalies else 'None'

        print(f"| {model_name:<16} | {condition:<16} | {n_seeds:>6} | {seed_str:<16} | {acc_str:<30} | {anom_str:<30} |")
    print("|" + "-"*18 + "|" + "-"*18 + "|" + "-"*8 + "|" + "-"*18 + "|" + "-"*32 + "|" + "-"*32 + "|")

